// ── Types ─────────────────────────────────────────────────────────────────────

type CasePriority = "P1" | "P2" | "P3" | "P4";
type CaseStatus = "new" | "triaged" | "investigating" | "contained" | "eradicating" | "recovering" | "closed" | "false-positive";
type CaseType = "Malware" | "Phishing" | "Data Breach" | "Ransomware" | "Insider Threat" | "DDoS" | "Unauthorized Access" | "Vulnerability Exploit" | "APT" | "Supply Chain" | "Fraud" | "Policy Violation";

type EvidenceItem = {
  id: string;
  type: "log" | "pcap" | "screenshot" | "memory_dump" | "file_hash" | "email" | "alert";
  description: string;
  addedBy: string;
  addedAt: string;
  hash?: string;
};

type TimelineEvent = {
  id: string;
  timestamp: string;
  actor: string;
  action: string;
  details: string;
  type: "detection" | "action" | "escalation" | "update" | "resolution";
};

// DB row shape — matches Supabase `cases` columns
type CaseRow = {
  id: string;
  title: string;
  description: string | null;
  priority: string;
  status: string;
  severity: string;
  category: string | null;
  assignee: string | null;
  created_by: string | null;
  affected_assets: string[] | null;
  iocs: string[] | null;
  tags: string[] | null;
  timeline: TimelineEvent[] | null;
  evidence: EvidenceItem[] | null;
  notes: string | null;
  closed_at: string | null;
  created_at: string;
  updated_at: string | null;
};

// Front-end shape used throughout this file
type SecurityCase = {
  id: string;
  title: string;
  type: CaseType;
  priority: CasePriority;
  status: CaseStatus;
  severity: "critical" | "high" | "medium" | "low";
  assignee: string;
  affectedAssets: string[];
  iocs: string[];
  detectedAt: string;
  slaDeadline: string;
  resolvedAt: string | null;
  description: string;
  evidence: EvidenceItem[];
  timeline: TimelineEvent[];
  notes: string;
  closureCode: string | null;
  aiAnalysis: string | null;
  aiAnalyzedAt: string | null;
};

// ── Mapping helpers ────────────────────────────────────────────────────────────

function rowToCase(row: CaseRow): SecurityCase {
  // Derive slaDeadline from created_at + priority-based SLA hours
  const slaHours: Record<string, number> = { P1: 4, P2: 24, P3: 72, P4: 168 };
  const h = slaHours[row.priority] ?? 72;
  const slaDeadline = new Date(new Date(row.created_at).getTime() + h * 3600000).toISOString();

  return {
    id: row.id,
    title: row.title,
    type: (row.category as CaseType) ?? "Malware",
    priority: (row.priority as CasePriority) ?? "P3",
    status: (row.status as CaseStatus) ?? "new",
    severity: (row.severity as SecurityCase["severity"]) ?? "medium",
    assignee: row.assignee ?? "Unassigned",
    affectedAssets: Array.isArray(row.affected_assets) ? row.affected_assets : [],
    iocs: Array.isArray(row.iocs)
      ? (row.iocs as string[])
      : (row.iocs && typeof row.iocs === "object")
        ? Object.values(row.iocs as Record<string, unknown>).flat().filter((v): v is string => typeof v === "string")
        : [],
    detectedAt: row.created_at,
    slaDeadline,
    resolvedAt: row.closed_at ?? null,
    description: row.description ?? "",
    evidence: Array.isArray(row.evidence) ? (row.evidence as EvidenceItem[]) : [],
    timeline: Array.isArray(row.timeline) ? (row.timeline as TimelineEvent[]) : [],
    notes: row.notes ?? "",
    closureCode: null,
    aiAnalysis: (row as any).ai_analysis ?? null,
    aiAnalyzedAt: (row as any).ai_analyzed_at ?? null,
  };
}

