// ── Helpers ───────────────────────────────────────────────────────────────────

function timeAgo(iso: string): string {
  const m = Math.floor((Date.now() - new Date(iso).getTime()) / 60000);
  if (m < 1) return "just now";
  if (m < 60) return `${m}m ago`;
  const h = Math.floor(m / 60);
  if (h < 24) return `${h}h ago`;
  return `${Math.floor(h / 24)}d ago`;
}

function slaRemaining(deadline: string): { label: string; overdue: boolean; urgentWarning: boolean } {
  const diff = new Date(deadline).getTime() - Date.now();
  const overdue = diff < 0;
  const hours = Math.abs(Math.floor(diff / 3600000));
  const mins = Math.abs(Math.floor((diff % 3600000) / 60000));
  const label = overdue
    ? `Overdue ${hours}h ${mins}m`
    : `${hours}h ${mins}m left`;
  return { label, overdue, urgentWarning: !overdue && diff < 7200000 };
}

function genEvId(): string {
  return `ev-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`;
}

// ── Sub-components ─────────────────────────────────────────────────────────────

function SLABadge({ deadline }: { deadline: string }) {
  const { label, overdue, urgentWarning } = slaRemaining(deadline);
  const cls = overdue
    ? "bg-red-500/15 text-red-400 border-red-500/40"
    : urgentWarning
    ? "bg-orange-500/15 text-orange-400 border-orange-500/40"
    : "bg-green-500/15 text-green-400 border-green-500/40";
  return (
    <Badge className={`${cls} text-xs whitespace-nowrap`}>
      <Clock className="w-3 h-3 mr-1" />
      {label}
    </Badge>
  );
}

